/**
 * resolveImage.ts
 *
 * Maps a known /assets/aistudio/<name>.png URL to its optimized WebP variants
 * (generated by `npm run images:optimize` and committed to
 * public/assets/optimized/).
 *
 * Any other URL — Supabase storage URLs, https:// URLs, relative paths that
 * don't match the aistudio pattern — is returned unchanged so that images
 * uploaded via the portal are unaffected.
 *
 * Usage:
 *   import { resolveImage } from '../lib/resolveImage'
 *   const img = resolveImage(url)
 *   <img src={img.src} srcSet={img.srcSet} sizes={img.sizes} />
 */

export interface ResolvedImage {
  /** Primary src — the 1600 w WebP (or original URL if not an aistudio asset). */
  src: string
  /**
   * srcSet string — three densities/widths for the browser to pick from.
   * Empty string when the URL is not a known aistudio asset.
   */
  srcSet: string
  /**
   * Sizes hint for the browser.
   * Empty string when the URL is not a known aistudio asset.
   */
  sizes: string
}

/** The PNG names that have optimized WebP variants. */
const KNOWN_NAMES = new Set([
  'image_1a90f9a9',
  'image_230557a2',
  'image_25e4d059',
  'image_3856f7f5',
  'image_6eb824fd',
  'image_731dbb07',
  'image_7544bf77',
  'image_9108d7cc',
  'image_a7c5afdc',
  'image_b3b470e9',
  'image_c7963080',
  'image_c9b19ed8',
  'image_d5bf61c0',
  'image_db590259',
  'image_dd2f8daf',
  'image_e2e72d06',
  'image_e6296589',
  'image_fe8a90e0',
])

/** Regex matching /assets/aistudio/<name>.png */
const AISTUDIO_RE = /^\/assets\/aistudio\/(image_[0-9a-f]+)\.png$/

/**
 * Resolve a URL to its optimized WebP variants.
 *
 * @param url - The image URL from the database or hardcoded fallback.
 * @returns A ResolvedImage with src, srcSet, and sizes.
 */
export function resolveImage(url: string | null | undefined): ResolvedImage {
  if (!url) {
    return { src: '/assets/aistudio/image_b3b470e9.png', srcSet: '', sizes: '' }
  }

  const match = AISTUDIO_RE.exec(url)
  if (!match) {
    // External URL, Supabase storage URL, or unknown path — return unchanged
    return { src: url, srcSet: '', sizes: '' }
  }

  const name = match[1]
  if (!KNOWN_NAMES.has(name)) {
    // PNG exists but we don't have optimized variants yet — serve original
    return { src: url, srcSet: '', sizes: '' }
  }

  const base = `/assets/optimized/${name}`
  return {
    src:    `${base}-1600.webp`,
    srcSet: `${base}-480.webp 480w, ${base}-960.webp 960w, ${base}-1600.webp 1600w`,
    // Most cards are ≤ 50 vw on desktop, full-width on mobile.
    // The hero and gallery lightbox use a separate sizes override.
    sizes:  '(min-width: 1024px) 50vw, (min-width: 640px) 80vw, 100vw',
  }
}

/**
 * Convenience: return only the src string for use in meta tags or
 * contexts where srcSet is not applicable (og:image, twitter:image, poster).
 */
export function resolveImageSrc(url: string | null | undefined): string {
  return resolveImage(url).src
}
